async function putMedia(id,file){if(!db)throw Error('Media storage is unavailable in this browser.');await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});mediaType[id]=file.type;if(media[id])URL.revokeObjectURL(media[id]);media[id]=URL.createObjectURL(file);return id}
function delMedia(id){if(media[id]){URL.revokeObjectURL(media[id]);delete media[id]}try{db?.transaction('files','readwrite').objectStore('files').delete(id)}catch{}}
function mediaURL(key){return media[key]||(!key?.startsWith('media-')?key:'')||''}
// Whether a stored file is a picture or a video. Uploaded files remember their type; built-in files go by their name.
const mediaType={};
const kindOf=key=>mediaType[key]||(/\.(mp4|webm|mov)(\?|$)/i.test(key||'')?'video/mp4':'image/webp');
const clipOf=key=>{const src=key&&mediaURL(key);return src?{src,type:kindOf(key)}:null};
