// The guide: talks people through building, out loud, in the phone voice (instant, no setup). Tap 🔊 to mute; remembered.
function guideSay(text){if(state.guideMute||!window.speechSynthesis||!text)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text),en=voices.find(v=>v.default&&/^en/i.test(v.lang))||voices.find(v=>/^en/i.test(v.lang));if(en)u.voice=en;u.rate=1.02;u.onstart=()=>guideBot.talk(true);u.onend=u.onerror=()=>guideBot.talk(false);speechSynthesis.speak(u)}catch{}}
function wireMute(){document.querySelectorAll('.guideMute').forEach(b=>{if(b.dataset.w)return;b.dataset.w=1;b.addEventListener('click',()=>{if(b.closest('.content'))return;state.guideMute=!state.guideMute;save();b.textContent=state.guideMute?'🔇 Guide off':'🔊 Guide on';if(state.guideMute)speechSynthesis?.cancel()})})}
function guideToggle(){return `<span class="guideBar"><button type="button" class="mini secondary guideMute" title="Guide voice" aria-label="Guide voice">${state.guideMute?'🔇 Guide off':'🔊 Guide on'}</button><button type="button" class="mini secondary guideTalk ${state.aiHelpUsed?'':'pulse'}" onclick="window.guideTalk&&guideTalk()" title="Tap this for AI assistance">${guideLive?'● Listening · tap to stop':state.aiHelpUsed?'🎙 AI help':'🎙 Tap this for AI assistance'}</button></span>`}
// ---- The guide on screen: a see-through floating android host in the corner, with her talk button glowing on her chest.
// She is any character picked in a library ("Use as the app's guide"); until one is picked, a hologram stand-in is drawn.
// She floats over everything except chats and story mode, moves into open windows so she stays tappable, and talks
// (her Talking clip, or a glow on the stand-in) while the guide speaks.
const guideBot=(()=>{let box=null,st=null,shownId='',talking=false;
  const STAND_IN=`<svg viewBox="0 0 100 150" class="gbSvg" aria-hidden="true"><defs><linearGradient id="gbG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#bff3ff"/><stop offset="1" stop-color="#5fb8ff" stop-opacity=".2"/></linearGradient></defs><g fill="none" stroke="url(#gbG)" stroke-width="2"><ellipse cx="50" cy="28" rx="15" ry="18"/><path d="M38 24h24M44 34q6 4 12 0"/><path d="M42 46v6M58 46v6M24 70q2-16 26-18q24 2 26 18l4 60H20z"/><path d="M30 80l-6 40M70 80l6 40"/></g><g fill="#bff3ff" opacity=".9"><circle cx="44" cy="25" r="1.8"/><circle cx="56" cy="25" r="1.8"/></g></svg>`;
  const who=()=>state.guideId?findCast(state.guideId):null,visible=()=>!state.guideHidden&&!['chat','story'].includes(view);
  function build(){box=document.createElement('div');box.id='guideBot';box.innerHTML=`<div class="gbHolo"><div class="gbFig"></div><button type="button" class="gbCore" aria-label="Tap this for AI assistance"></button></div><div class="gbLabel">Tap my light for AI help</div><button type="button" class="gbHide" aria-label="Hide the guide">–</button>`;
    box.querySelector('.gbCore').onclick=()=>guideTalk();box.querySelector('.gbHide').onclick=()=>{state.guideHidden=true;save();place();toast('Guide hidden. Tap any 🎙 AI help button to bring her back.')}}
  function fill(){const c=who(),fig=box.querySelector('.gbFig'),id=c?.id||'';if(id===shownId&&fig.childElementCount)return;shownId=id;st?.destroy?.();st=null;fig.innerHTML='';box.classList.toggle('standin',!c);const cy=(c?.outfit&&(c.outfits||[]).find(o=>o.id===c.outfit)?.coreY)||c?.coreY;box.querySelector('.gbCore').style.top=cy?`calc(${cy}% - 8px)`:'';
    if(!c){fig.innerHTML=STAND_IN;return}const clips=charClips(c);if(!clips.normal){fig.innerHTML=STAND_IN;box.classList.add('standin');return}const host=document.createElement('div');host.className='gbStage';fig.appendChild(host);st=createStage(host);st.setCharacter(clips,c.chroma||'none',c.spill??0.8);const me=st;setTimeout(()=>{if(st===me&&!talking)stroll()},700)}
  function stroll(){try{if(st?.has('walk')&&!talking&&!guideLive&&!document.hidden)st.show('walk',{force:false})}catch{}}
  setInterval(stroll,55000);
  function place(){if(!visible()){box?.remove();return}if(!box)build();const host=$('#modal').open?$('#modal'):document.body;if(box.parentElement!==host)host.appendChild(box);fill();sync()}
  function sync(){if(!box)return;box.classList.toggle('talking',talking);box.classList.toggle('live',guideLive);box.querySelector('.gbLabel').textContent=guideLive?'Listening · tap my light to stop':state.aiHelpUsed?'AI help':'Tap my light for AI help'}
  new MutationObserver(()=>place()).observe($('#modal'),{attributes:true,attributeFilter:['open']});
  return {place,sync,wave(){try{if(st?.has('wave'))st.show('wave')}catch{}},talk(on){talking=!!on;try{st?.speaking(talking)}catch{}sync()},refresh(){shownId='';if(box)fill()}}})();
// Ask the guide anything about the app, by typing or by voice. It answers in plain words, out loud, then you carry on where you were.
const GUIDE_FACTS=`You are Aurora, the friendly android guide inside My Echo Vision, an app where you talk with story characters over a scene, like a video call. Answer the person's question about using the app in 1 to 3 short, plain sentences, warm and simple, no lists, no markdown. If you don't know, say so and suggest the closest thing.
How the app works:
- Home has three ways in: Quick start (three pictures: one of yourself, one of the scene, one of who you want to talk to), One tap (makes everything and starts), and Advanced (the cast, where every character has a library).
- Quick start steps: 1 Who are you? Take or upload a photo, or pick one of ours; it's your protagonist, and your picture just helps the characters recognize you. 2 Choose a scene: a photo, a looping video of 15 seconds or less (recommended, best when it loops with no jump), or for advanced users a 3D .glb world; ready-made ones are there. 3 Who are you going to meet? A roster, three across; tap someone to zoom in, read or write who they are, or tap Auto persona; tap Meet. 4 Your story: write it or tap Auto outline, then Begin story.
- A persona means who the character is: their personality, background and how they talk.
- Voice: the phone voice works instantly. To clone a voice, upload a voice clip, or copy the voice prompt, make a 10 second talking video with sound in a video generator, and upload it; the voice is pulled out and cloned.
- Wardrobe: add pictures of a character in other outfits any time; tap an outfit to wear it, so the characters recognize the look.
- A character's library holds their picture or idle loop, voice, persona, wardrobe, base pictures, every expression (Normal, Talking, Happy, Sad, Surprised, Angry, Scared, Yes, No), actions (dances, wave, laugh, thinking, your own), and walks. Each slot has Copy prompt and Upload. You make clips yourself in a video generator using the prompt and the base picture.
- Base pictures: the main one is waist up, 2:3 portrait, camera at waist height, on a plain green screen (blue if green is on the character). The close walk is knees up, 16:9; the far walk is full body, 16:9. 480 is enough for phones; use 720 or more for a big widescreen.
- Clips are 15 seconds or less, silent, start and end on the base picture so they loop, with the same framing every time. No lip sync; one Talking clip covers speech.
- Making characters needs only your own or invented faces and voices, or ones you have permission to use.
- The guide voice can be turned off with the Guide button.`;
const guideHistory=[];let guideLive=false,guideRec=null;
// Speak and wait until done, so the talk button does not hear the guide's own voice.
function guideSayWait(text){return new Promise(res=>{if(state.guideMute||!window.speechSynthesis)return res();try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text),en=voices.find(v=>v.default&&/^en/i.test(v.lang))||voices.find(v=>/^en/i.test(v.lang));if(en)u.voice=en;u.rate=1.02;let done=false;const fin=()=>{guideBot.talk(false);if(!done){done=true;res()}};u.onstart=()=>guideBot.talk(true);u.onend=fin;u.onerror=fin;setTimeout(fin,Math.min(30000,1500+text.length*80));speechSynthesis.speak(u)}catch{res()}})}
async function guideAnswer(text){const ans=$('#gpAnswer');if(ans)ans.textContent='Thinking…';if(!brainReady()){const m='I need the AI brain to answer questions. It is usually on by default; check the Brain page.';if(ans)ans.textContent=m;return m}
  const where=`The person is on: ${view==='setup'?['Who are you','Choose a scene','Who will you meet','Your story'][step]+' step':view}${$('#modal').open?', in the window titled "'+($('#modal h2')?.textContent||'')+'"':''}.`;
  try{const a=await brain.write(state.brainCfg,[{role:'system',content:GUIDE_FACTS+'\n'+where},...guideHistory.slice(-6),{role:'user',content:text}],260);const say=(a||'Sorry, I did not catch that. Try asking another way.').replace(/[*#_`]/g,'').trim();guideHistory.push({role:'user',content:text},{role:'assistant',content:say});if($('#gpAnswer'))$('#gpAnswer').textContent=say;return say}catch{const m='Sorry, I could not reach the AI brain just now. Try again in a moment.';if($('#gpAnswer'))$('#gpAnswer').textContent=m;return m}}
function guidePanel(){let host=$('#modal').open?$('#modal'):document.body,panel=document.getElementById('guidePanel');if(panel&&panel.parentElement!==host){panel.remove();panel=null}if(panel)return panel;
  panel=document.createElement('div');panel.id='guidePanel';panel.innerHTML=`<div class="gpHead"><strong>AI help</strong><button type="button" class="mini secondary" id="gpClose" aria-label="Close">×</button></div><p id="gpAnswer" class="sub" style="margin:6px 0">Ask me anything. For example: what is a persona, or how do I clone a voice?</p><div class="row"><input id="gpQ" maxlength="300" placeholder="Or type your question" style="flex:1;min-width:0"><button type="button" class="mini primary" id="gpGo">Ask</button></div>`;host.appendChild(panel);if(host.id==='modal')host.addEventListener('close',guideTalkStop,{once:true});
  const q=panel.querySelector('#gpQ'),go=async()=>{const t=q.value.trim();if(!t)return;q.value='';const say=await guideAnswer(t);guideSay(say)};panel.querySelector('#gpGo').onclick=go;q.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();go()}};panel.querySelector('#gpClose').onclick=()=>{guideTalkStop();panel.remove()};return panel}
function guideTalkSync(){guideBot.sync();document.querySelectorAll('.guideTalk').forEach(b=>{b.classList.toggle('on',guideLive);b.textContent=guideLive?'● Listening · tap to stop':state.aiHelpUsed?'🎙 AI help':'🎙 Tap this for AI assistance';if(state.aiHelpUsed)b.classList.remove('pulse')})}
function guideTalkStop(){guideLive=false;try{guideRec?.abort()}catch{}guideRec=null;guideTalkSync()}
// The talk button: tap and it turns red and listens; ask out loud, it answers out loud; tap again to turn it off.
function guideTalk(){if(state.guideHidden){state.guideHidden=false;save();guideBot.place()}if(guideLive){guideTalkStop();return}guidePanel();const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Talking is unavailable in this browser. Type your question instead.');$('#gpQ')?.focus();return}
  if(!state.aiHelpUsed){state.aiHelpUsed=1;save();guideBot.wave()}guideLive=true;guideTalkSync();const listen=()=>{if(!guideLive)return;const r=guideRec=new SR();r.lang=navigator.language||'en-US';r.interimResults=false;let heard=false;
    r.onresult=async e=>{heard=true;const t=e.results[0][0].transcript;if($('#gpAnswer'))$('#gpAnswer').textContent='“'+t+'”';const say=await guideAnswer(t);if(guideLive){await guideSayWait(say);listen()}};
    r.onerror=e=>{if(e.error==='not-allowed'){toast('Microphone permission was declined. Type your question instead.');guideTalkStop()}};
    r.onend=()=>{if(guideLive&&!heard)setTimeout(listen,200)};try{r.start()}catch{}};
  guideSayWait(state.aiHelpFirst?'I\'m listening. What would you like to know?':(state.aiHelpFirst=1,save(),'Hi! I\'m Aurora, I\'m right here, and I can hear you. Ask me anything about building your story, like what\'s a persona, or how do I clone a voice.')).then(listen)}
function askGuide(){guideTalk()}
window.askGuide=askGuide;window.guideTalk=guideTalk;
function wireGuide(first){document.querySelectorAll('.guideMute').forEach(b=>b.onclick=()=>{state.guideMute=!state.guideMute;save();b.textContent=state.guideMute?'🔇 Guide off':'🔊 Guide on';if(state.guideMute)speechSynthesis?.cancel();else guideSay(first)});$('#modal').addEventListener('close',()=>{try{speechSynthesis.cancel()}catch{}},{once:true});guideSay(first)}
// ---- Wardrobe: each character keeps a chain of outfits (pictures in other clothes or uniforms), added as you go.
// Wearing one swaps the character's picture and look, so everything else (recognition, the brain, the stage)
// sees the right outfit. The main picture is kept in c.main while another outfit is worn.
function outfitList(c){return [{id:'',name:'Main',image:(c.outfit?c.main?.image:c.image)||''},...(c.outfits||[])]}
// Each outfit can have its own clips (its own idle, talking…); an outfit without clips shows its picture.
function wearOutfit(c,oid){oid=oid||'';if((c.outfit||'')===oid)return;const cur=c.outfit?(c.outfits||[]).find(o=>o.id===c.outfit):null;if(cur){cur.image=c.image;cur.look=c.look||'';cur.lookOf=c.lookOf||'';cur.clips=c.clips||{}}else c.main={image:c.image,look:c.look||'',lookOf:c.lookOf||'',lookEdited:c.lookEdited,clips:c.clips||{}};const next=oid?(c.outfits||[]).find(o=>o.id===oid):c.main;if(!next)return;c.image=next.image;c.look=next.look||'';c.lookOf=next.lookOf||'';c.clips=structuredClone(next.clips||{});if(!oid){c.lookEdited=c.main?.lookEdited;delete c.main}c.outfit=oid;save();if(c.id===state.guideId)guideBot.refresh()}
function outfitChips(c,attr){if(!c)return '';const list=outfitList(c);return `<div class="outfits"><span class="footerNote" style="margin:0">${list.length>1?`${esc(c.name)} is wearing:`:'Outfits:'}</span>${list.length>1?list.map(o=>`<button type="button" class="mini ${(c.outfit||'')===o.id?'primary':'secondary'}" data-${attr}="${esc(o.id)}">${esc(o.name)}</button>`).join(''):''}<button type="button" class="mini secondary" data-addfit="${esc(c.id)}">＋ Add outfit</button></div>`}
// Open a character at their wardrobe, any time, to add the next outfit the story needs.
