const MOODS=['calm','mellow','romantic','scary','epic','epic chase','epic fight'];
const BUILTIN_MUSIC=[{id:'m-spaceways',name:'Spaceways',src:'assets/music/spaceways_1.m4a',mood:'calm'},{id:'m-veranthos',name:'Veranthos',src:'assets/music/veranthos_1.m4a',mood:'mellow'},{id:'m-rift1',name:'Rift 1',src:'assets/music/rift_1.m4a',mood:'epic fight'},{id:'m-rift2',name:'Rift 2',src:'assets/music/rift_2.m4a',mood:'epic chase'}];
